692:     boss.hit = 0.11;
693:     if (boss.hp <= 0) {
694:       boss.hp = 0;
695:       burst(boss.x, boss.y - 45, "#ffb04e", 42, 300);
696:       burst(boss.x, boss.y - 45, "#ff4e83", 28, 250);
697:       dropCoins(boss.x, boss.y - 25, 55 + meta.sector * 5);
