700:       boss = null;
701:       run.bossDefeated = true;
702:       ui.bossHud.classList.remove("active");
703:       ui.waveHud.classList.remove("boss-wave");
704:       shake = 18; flash = 0.22; flashColor = "255,219,89";
705:       sound("bossdown");
706:       window.setTimeout(() => { if (scene === "playing" && run?.bossDefeated) finishRun(true); }, 900);
707:     }
708:   }
