755:   function updateGame(dt) {
756:     if (scene !== "playing" || !run || !player) return;
757:     run.elapsed += dt;
758:     run.scroll += dt * 115;
759:     player.runPhase += dt * 11;
760:     player.recoil = Math.max(0, player.recoil - dt * 5.5);
761:     player.invuln = Math.max(0, player.invuln - dt);
762:     player.hitFlash = Math.max(0, player.hitFlash - dt);
763:     player.muzzle = Math.max(0, player.muzzle - dt * 7);
764:     player.muzzleBurst = Math.max(0, player.muzzleBurst - dt * 5);
765:     if (input.aiming && input.pointer) {
766:       const gunX = player.x + 37 * playerScale();
767:       const gunY = player.y - 54 * playerScale();
768:       player.desiredAim = clamp(Math.atan2(gunY - input.pointer.y, input.pointer.x - gunX), -1.32, 0.3);
769:     } else if (!input.usedAim) {
770:       const target = nearestTarget(player.x + 40, player.y - 55, 1.8);
771:       if (target) player.desiredAim = clamp(Math.atan2(target.y - player.y + 55 * playerScale(), target.x - player.x - 38 * playerScale()), -1.22, 0.22);
772:     }
773:     let angleDelta = player.desiredAim - player.aimAngle;
774:     while (angleDelta > Math.PI) angleDelta -= TAU;
775:     while (angleDelta < -Math.PI) angleDelta += TAU;
776:     player.aimAngle += angleDelta * Math.min(1, dt * 12);
777: 
778:     if (!run.bossDefeated) {
779:       if (run.spawnLeft > 0) {
780:         run.spawnTimer -= dt;
781:         if (run.spawnTimer <= 0) {
782:           enemies.push(makeEnemy()); run.spawnLeft--; run.totalSpawned++;
783:           run.spawnTimer = Math.max(0.38, rand(0.72, 1.05) - run.level.difficulty * 0.035);
784:         }
785:       } else if (enemies.length === 0 && !boss) {
786:         run.intermission += dt;
787:         if (run.intermission > 1.2) { run.intermission = 0; beginNextWave(); }
788:       }
789:     }
790: 
791:     const weapon = getWeapon();
792:     const fireRate = weapon.rate * Math.max(0.52, 1 - upgradeValue("fire") * 0.07);
793:     player.fireCd -= dt;
794:     if (player.fireCd <= 0 && !run.bossDefeated) {
795:       const muzzleX = player.x + 38 * playerScale();
796:       const muzzleY = player.y - 57 * playerScale();
797:       let fireAngle = player.aimAngle;
798:       if (!input.usedAim) {
799:         const target = nearestTarget(muzzleX, muzzleY, 2.4);
800:         if (target) fireAngle = Math.atan2(target.y - muzzleY, target.x - muzzleX);
801:       }
802:       player.fireCd = fireRate;
803:       player.recoil = 1; player.muzzle = 1; player.muzzleBurst = 1;
804:       for (let i = 0; i < weapon.pellets; i++) {
805:         const a = fireAngle + rand(-weapon.spread, weapon.spread);
806:         bullets.push({ x: muzzleX, y: muzzleY, vx: Math.cos(a) * weapon.speed, vy: Math.sin(a) * weapon.speed, damage: weapon.damage * (1 + upgradeValue("damage") * 0.12), color: weapon.color, life: 1.45, r: weapon.id === "rocket" ? 5 : 3, splash: weapon.splash || 0, chain: weapon.chain || 0, hitIds: [] });
807:       }
808:       burst(muzzleX, muzzleY, weapon.color, weapon.id === "rocket" ? 5 : 2, 55);
809:       sound("shot", weapon.id);
810:     }
811: 
812:     for (const enemy of enemies) {
813:       enemy.bob += dt * (enemy.type === "runner" ? 7 : 4);
814:       enemy.hit = Math.max(0, enemy.hit - dt);
815:       enemy.attackCd -= dt;
816:       enemy.spitCd -= dt;
817:       const targetX = player.x + 61;
818:       if (enemy.x > targetX) enemy.x -= enemy.speed * dt;
819:       else if (enemy.attackCd <= 0) { enemy.attackCd = enemy.type === "brute" ? 0.92 : 0.72; damagePlayer(enemy.damage); }
820:       if (enemy.type === "spitter" && enemy.spitCd <= 0 && enemy.x > player.x + 135 && enemy.x < view.W + 20) {
821:         enemy.spitCd = rand(2.2, 3.2);
822:         const dx = player.x + 20 - enemy.x; const dy = player.y - 45 - enemy.y;
823:         const a = Math.atan2(dy, dx);
824:         hazards.push({ x: enemy.x - 10, y: enemy.y - 20, vx: Math.cos(a) * 235, vy: Math.sin(a) * 235, life: 3, r: 7, damage: enemy.damage * 0.75, color: "#ce78b6" });
825:       }
826:     }
827: 
828:     if (boss) {
829:       boss.bob += dt * 2.6; boss.hit = Math.max(0, boss.hit - dt); boss.attackCd -= dt;
830:       boss.x = Math.max(view.W * 0.7, boss.x - 24 * dt);
831:       boss.y = view.groundY - 70 * actorScale() + Math.sin(boss.bob) * 8;
832:       if (boss.attackCd <= 0) {
833:         boss.attackCd = Math.max(0.8, 1.7 - run.level.difficulty * 0.04);
834:         const a = Math.atan2(player.y - 55 * playerScale() - boss.y, player.x + 20 - boss.x);
835:         const spread = run.level.sector > 3 ? [-0.13, 0, 0.13] : [0];
836:         for (const offset of spread) hazards.push({ x: boss.x - 36, y: boss.y - 26, vx: Math.cos(a + offset) * 290, vy: Math.sin(a + offset) * 290, life: 3, r: 10, damage: 15 + run.level.difficulty * 1.5, color: "#ff597a" });
837:         burst(boss.x - 30, boss.y - 26, "#ff597a", 5, 65); sound("spit");
838:       }
839:     }
840: 
841:     for (const bullet of bullets) {
842:       bullet.x += bullet.vx * dt; bullet.y += bullet.vy * dt; bullet.life -= dt;
843:       for (const enemy of enemies) {
844:         if (enemy.dead || bullet.hitIds.includes(enemy.id)) continue;
845:         if (Math.hypot(enemy.x - bullet.x, enemy.y - enemy.radius * 0.5 - bullet.y) < enemy.radius * 0.8 + bullet.r) {
846:           enemy.hp -= bullet.damage; enemy.hit = 0.12; bullet.life = 0;
847:           burst(bullet.x, bullet.y, bullet.color, 3, 70); sound("impact");
848:           if (bullet.splash) for (const other of enemies) if (!other.dead && other !== enemy && Math.hypot(other.x - enemy.x, other.y - enemy.y) < bullet.splash) other.hp -= bullet.damage * 0.65;
849:           if (bullet.chain) {
850:             let left = bullet.chain;
851:             for (const other of enemies) if (!other.dead && other !== enemy && Math.hypot(other.x - enemy.x, other.y - enemy.y) < 150 && left-- > 0) { other.hp -= bullet.damage * 0.65; burst(other.x, other.y - 10, "#69efff", 6, 95); }
852:           }
853:           if (enemy.hp <= 0) killEnemy(enemy);
854:           break;
855:         }
856:       }
857:       if (boss && bullet.life > 0 && Math.hypot(boss.x - bullet.x, boss.y - 28 - bullet.y) < boss.radius * 0.82 + bullet.r) { hurtBoss(bullet.damage); bullet.life = 0; burst(bullet.x, bullet.y, bullet.color, 4, 90); }
858:     }
859:     bullets = bullets.filter((bullet) => bullet.life > 0 && bullet.x < view.W + 80 && bullet.y > -30 && bullet.y < view.H + 20);
860:     enemies = enemies.filter((enemy) => !enemy.dead && enemy.x > -80);
861: 
862:     for (const hazard of hazards) {
863:       hazard.x += hazard.vx * dt; hazard.y += hazard.vy * dt; hazard.life -= dt;
864:       if (Math.hypot(hazard.x - player.x, hazard.y - (player.y - 52 * playerScale())) < hazard.r + 28 * playerScale()) { hazard.life = 0; damagePlayer(hazard.damage); burst(hazard.x, hazard.y, hazard.color, 8, 110); }
865:     }
866:     hazards = hazards.filter((hazard) => hazard.life > 0 && hazard.x > -30 && hazard.x < view.W + 30);
867: 
868:     for (const coin of pickups) {
869:       coin.phase += dt * 5; coin.vy += 360 * dt; coin.x += coin.vx * dt; coin.y += coin.vy * dt;
870:       const magnet = 100 + upgradeValue("magnet") * 45;
871:       const distance = Math.hypot(player.x - coin.x, player.y - coin.y);
872:       if (distance < magnet) { const force = (1 - distance / magnet) * 580; coin.vx += (player.x - coin.x) / Math.max(1, distance) * force * dt; coin.vy += (player.y - coin.y) / Math.max(1, distance) * force * dt; }
873:       if (distance < 45 * playerScale()) { run.coins += coin.value; coin.life = 0; burst(coin.x, coin.y, "#ffe66d", 4, 75); floatText(player.x, player.y - 110, `+${coin.value}`, "#ffe66d"); sound("coin"); }
874:       coin.life -= dt;
875:     }
876:     pickups = pickups.filter((coin) => coin.life > 0 && coin.y < view.H + 30);
877: 
878:     for (const part of particles) { part.life -= dt; part.x += part.vx * dt; part.y += part.vy * dt; part.vx *= Math.pow(0.1, dt); part.vy += (part.gravity || 0) * dt; }
879:     particles = particles.filter((part) => part.life > 0);
880:     for (const floater of floaters) { floater.life -= dt; floater.y -= 30 * dt; }
881:     floaters = floaters.filter((floater) => floater.life > 0);
882:     run.comboTimer -= dt;
883:     if (run.comboTimer <= 0) run.combo = 0;
884:     shake = Math.max(0, shake - dt * 24);
