301:   function buildBackdrop() {
302:     const theme = THEMES[run ? run.level.themeIndex : Math.floor(((meta.sector || 1) - 1) / 2) % THEMES.length];
303:     const key = theme.id;
304:     if (backdrop && backdropTheme === key) return;
305: 
306:     const dpr = view.DPR;
307:     const c = document.createElement("canvas");
308:     c.width = Math.round(view.W * dpr);
309:     c.height = Math.round(view.H * dpr);
310:     const g = c.getContext("2d");
311:     g.setTransform(dpr, 0, 0, dpr, 0, 0);
312: 
313:     const W = view.W;
314:     const H = view.H;
315:     const horizon = view.horizonY;
316: 
317:     const sky = g.createLinearGradient(0, 0, 0, horizon + 10);
318:     sky.addColorStop(0, theme.sky[0]);
319:     sky.addColorStop(0.4, theme.sky[1]);
320:     sky.addColorStop(0.72, theme.sky[2]);
321:     sky.addColorStop(1, theme.sky[3]);
322:     g.fillStyle = sky;
323:     g.fillRect(0, 0, W, horizon + 14);
324: 
325:     // Stars in the darker part of the sky.
326:     for (let i = 0; i < 52; i++) {
327:       const x = hash(i * 3.1) * W;
328:       const y = hash(i * 7.7 + 2) * horizon * 0.48;
329:       const a = 0.16 + hash(i * 4.8) * 0.5;
330:       g.fillStyle = `rgba(255,255,255,${a * (1 - y / (horizon * 0.7))})`;
331:       g.fillRect(x, y, hash(i * 2.3) > 0.86 ? 2 : 1, hash(i * 2.3) > 0.86 ? 2 : 1);
332:     }
333: 
334:     // Sundown disc with soft halo.
335:     const sunX = W * (W > 700 ? 0.72 : 0.64);
336:     const sunY = horizon * 0.42;
337:     const sunR = Math.min(W, H) * (W > 700 ? 0.1 : 0.16);
338:     const halo = g.createRadialGradient(sunX, sunY, 0, sunX, sunY, sunR * 3.6);
339:     halo.addColorStop(0, theme.sunGlow);
340:     halo.addColorStop(0.45, theme.sunGlow.replace(/[\d.]+\)$/, "0.15)"));
341:     halo.addColorStop(1, "rgba(255,255,255,0)");
342:     g.fillStyle = halo;
343:     g.fillRect(sunX - sunR * 4, sunY - sunR * 4, sunR * 8, sunR * 8);
344:     g.fillStyle = theme.sun;
345:     g.beginPath();
346:     g.arc(sunX, sunY, sunR, 0, TAU);
347:     g.fill();
348: 
349:     // Retro bands across the lower half of the sun.
350:     g.save();
351:     g.beginPath();
352:     g.arc(sunX, sunY, sunR, 0, TAU);
353:     g.clip();
354:     g.fillStyle = "rgba(20, 12, 40, 0.18)";
355:     for (let i = 0; i < 5; i++) {
356:       const h = 2 + i * 1.8;
357:       g.fillRect(sunX - sunR, sunY + sunR * (0.2 + i * 0.13), sunR * 2, h);
358:     }
359:     g.restore();
360: 
361:     // Layered mountain silhouettes.
362:     drawMountainLayer(g, W, horizon, theme.far, 0.55, 0.36, 8, 1001);
363:     drawMountainLayer(g, W, horizon, theme.mid, 0.4, 0.5, 7, 2029);
364: 
365:     // Era-appropriate ruins on the skyline.
366:     g.save();
367:     g.fillStyle = theme.city;
368:     for (let i = 0; i < 14; i++) {
369:       const x = hash(i * 6.7 + 11) * W;
370:       const h = 20 + hash(i * 3.3 + 4) * horizon * 0.25;
371:       const w = 18 + hash(i * 8.1) * 44;
372:       g.fillRect(x, horizon - h, w, h);
373:       if (i % 3 === 0) g.fillRect(x + w * 0.3, horizon - h - 12, w * 0.16, 12);
374:       g.fillStyle = theme.sunGlow;
375:       for (let wy = horizon - h + 9; wy < horizon - 5; wy += 16) {
376:         if (hash(i * 14 + wy) > 0.58) g.fillRect(x + 5, wy, 3, 5);
377:       }
378:       g.fillStyle = theme.city;
379:     }
380:     g.restore();
381: 
382:     // Soft atmospheric haze at the horizon.
383:     const haze = g.createLinearGradient(0, horizon - 70, 0, horizon + 20);
384:     haze.addColorStop(0, "rgba(255,255,255,0)");
385:     haze.addColorStop(0.65, theme.haze);
386:     haze.addColorStop(1, "rgba(255,255,255,0)");
387:     g.fillStyle = haze;
388:     g.fillRect(0, horizon - 70, W, 90);
389: 
390:     // Cloud bands.
391:     g.save();
392:     for (let i = 0; i < 8; i++) {
393:       const y = horizon * (0.12 + hash(i * 9.2) * 0.55);
394:       const x = hash(i * 2.7 + 5) * W;
395:       const w = 40 + hash(i * 5.8) * 150;
396:       g.fillStyle = `rgba(255, 218, 201, ${0.035 + hash(i * 4.4) * 0.075})`;
397:       g.beginPath();
398:       g.ellipse(x, y, w, 5 + hash(i) * 3, 0, 0, TAU);
399:       g.fill();
400:     }
401:     g.restore();
402: 
403:     backdrop = c;
404:     backdropTheme = key;
405:   }
