598:     run = { level: getLevel(meta.sector), wave: 1, waves: 3, waveKills: 0, waveGoal: 6 + Math.min(5, Math.floor(meta.sector / 2)), spawnLeft: 6 + Math.min(5, Math.floor(meta.sector / 2)), spawnTimer: 0.6, intermission: 0, kills: 0, coins: 0, bestCombo: 0, combo: 0, comboTimer: 0, elapsed: 0, scroll: 0, totalSpawned: 0, bossDefeated: false, lastShot: 0 };
599:     enemies = []; bullets = []; hazards = []; pickups = []; particles = []; floaters = []; boss = null;
