658:   function damagePlayer(amount) {
659:     if (!player || player.invuln > 0 || scene !== "playing") return;
660:     const reduction = Math.min(0.38, upgradeValue("armor") * 0.035);
661:     player.hp -= amount * (1 - reduction);
662:     player.invuln = 0.68;
663:     player.hitFlash = 0.24;
664:     shake = Math.max(shake, 7);
665:     flash = Math.max(flash, 0.12);
666:     flashColor = "255,65,112";
667:     burst(player.x + 10, player.y - 42 * playerScale(), "#ff526f", 8, 150);
668:     sound("hurt");
669:     if (player.hp <= 0) finishRun(false);
