672:   function killEnemy(enemy) {
673:     if (enemy.dead) return;
674:     enemy.dead = true;
675:     run.kills++;
676:     run.waveKills++;
677:     run.combo++;
678:     run.comboTimer = 2.15;
679:     run.bestCombo = Math.max(run.bestCombo, run.combo);
680:     const payout = enemy.type === "brute" ? 5 : 3;
681:     const bonus = run.combo > 1 && run.combo % 5 === 0 ? 5 : 0;
682:     dropCoins(enemy.x, enemy.y - 12, payout + bonus);
683:     burst(enemy.x, enemy.y - enemy.radius * 0.55, enemy.color, enemy.type === "brute" ? 15 : 10, 190);
684:     floatText(enemy.x, enemy.y - enemy.radius, `+${payout + bonus}`, "#ffe66d");
685:     shake = Math.max(shake, enemy.type === "brute" ? 4 : 2);
686:     sound("kill");
687:   }
