301:   function buildBackdrop() {
302:     const theme = THEMES[run ? run.level.themeIndex : Math.floor(((meta.sector || 1) - 1) / 2) % THEMES.length];
303:     const key = theme.id;
304:     if (backdrop && backdropTheme === key) return;
305: 
306:     const dpr = view.DPR;
307:     const c = document.createElement("canvas");
308:     c.width = Math.round(view.W * dpr);
309:     c.height = Math.round(view.H * dpr);
310:     const g = c.getContext("2d");
311:     g.setTransform(dpr, 0, 0, dpr, 0, 0);
312: 
313:     const W = view.W;
314:     const H = view.H;
315:     const horizon = view.horizonY;
316: 
317:     const sky = g.createLinearGradient(0, 0, 0, horizon + 10);
318:     sky.addColorStop(0, theme.sky[0]);
319:     sky.addColorStop(0.4, theme.sky[1]);
320:     sky.addColorStop(0.72, theme.sky[2]);
321:     sky.addColorStop(1, theme.sky[3]);
322:     g.fillStyle = sky;
323:     g.fillRect(0, 0, W, horizon + 14);
324: 
325:     // Stars in the darker part of the sky.
326:     for (let i = 0; i < 52; i++) {
327:       const x = hash(i * 3.1) * W;
328:       const y = hash(i * 7.7 + 2) * horizon * 0.48;
329:       const a = 0.16 + hash(i * 4.8) * 0.5;
330:       g.fillStyle = `rgba(255,255,255,${a * (1 - y / (horizon * 0.7))})`;
331:       g.fillRect(x, y, hash(i * 2.3) > 0.86 ? 2 : 1, hash(i * 2.3) > 0.86 ? 2 : 1);
332:     }
333: 
334:     // Sundown disc with soft halo.
335:     const sunX = W * (W > 700 ? 0.72 : 0.64);
336:     const sunY = horizon * 0.42;
337:     const sunR = Math.min(W, H) * (W > 700 ? 0.1 : 0.16);
338:     const halo = g.createRadialGradient(sunX, sunY, 0, sunX, sunY, sunR * 3.6);
339:     halo.addColorStop(0, theme.sunGlow);
340:     halo.addColorStop(0.45, theme.sunGlow.replace(/[\d.]+\)$/, "0.15)"));
341:     halo.addColorStop(1, "rgba(255,255,255,0)");
342:     g.fillStyle = halo;
343:     g.fillRect(sunX - sunR * 4, sunY - sunR * 4, sunR * 8, sunR * 8);
344:     g.fillStyle = theme.sun;
345:     g.beginPath();
346:     g.arc(sunX, sunY, sunR, 0, TAU);
347:     g.fill();
348: 
349:     // Retro bands across the lower half of the sun.
350:     g.save();
351:     g.beginPath();
352:     g.arc(sunX, sunY, sunR, 0, TAU);
353:     g.clip();
354:     g.fillStyle = "rgba(20, 12, 40, 0.18)";
355:     for (let i = 0; i < 5; i++) {
356:       const h = 2 + i * 1.8;
357:       g.fillRect(sunX - sunR, sunY + sunR * (0.2 + i * 0.13), sunR * 2, h);
358:     }
359:     g.restore();
360: 
361:     // Layered mountain silhouettes.
362:     drawMountainLayer(g, W, horizon, theme.far, 0.55, 0.36, 8, 1001);
363:     drawMountainLayer(g, W, horizon, theme.mid, 0.4, 0.5, 7, 2029);
364: 
365:     // Era-appropriate ruins on the skyline.
366:     g.save();
367:     g.fillStyle = theme.city;
368:     for (let i = 0; i < 14; i++) {
369:       const x = hash(i * 6.7 + 11) * W;
370:       const h = 20 + hash(i * 3.3 + 4) * horizon * 0.25;
371:       const w = 18 + hash(i * 8.1) * 44;
372:       g.fillRect(x, horizon - h, w, h);
373:       if (i % 3 === 0) g.fillRect(x + w * 0.3, horizon - h - 12, w * 0.16, 12);
374:       g.fillStyle = theme.sunGlow;
375:       for (let wy = horizon - h + 9; wy < horizon - 5; wy += 16) {
376:         if (hash(i * 14 + wy) > 0.58) g.fillRect(x + 5, wy, 3, 5);
377:       }
378:       g.fillStyle = theme.city;
379:     }
380:     g.restore();
381: 
382:     // Soft atmospheric haze at the horizon.
383:     const haze = g.createLinearGradient(0, horizon - 70, 0, horizon + 20);
384:     haze.addColorStop(0, "rgba(255,255,255,0)");
385:     haze.addColorStop(0.65, theme.haze);
386:     haze.addColorStop(1, "rgba(255,255,255,0)");
387:     g.fillStyle = haze;
388:     g.fillRect(0, horizon - 70, W, 90);
389: 
390:     // Cloud bands.
391:     g.save();
392:     for (let i = 0; i < 8; i++) {
393:       const y = horizon * (0.12 + hash(i * 9.2) * 0.55);
394:       const x = hash(i * 2.7 + 5) * W;
395:       const w = 40 + hash(i * 5.8) * 150;
396:       g.fillStyle = `rgba(255, 218, 201, ${0.035 + hash(i * 4.4) * 0.075})`;
397:       g.beginPath();
398:       g.ellipse(x, y, w, 5 + hash(i) * 3, 0, 0, TAU);
399:       g.fill();
400:     }
401:     g.restore();
402: 
403:     backdrop = c;
404:     backdropTheme = key;
405:   }
406: 
407:   function drawMountainLayer(g, W, horizon, color, alpha, heightRatio, count, seed) {
408:     g.save();
409:     g.globalAlpha = alpha;
410:     g.fillStyle = color;
411:     g.beginPath();
412:     g.moveTo(-20, horizon + 20);
413:     const segment = W / count;
414:     for (let i = 0; i <= count; i++) {
415:       const peak = horizon - heightRatio * horizon * (0.5 + hash(seed + i * 2.73) * 0.7);
416:       g.lineTo(i * segment + hash(seed + i) * segment * 0.2, peak);
417:       g.lineTo((i + 0.5) * segment, horizon - heightRatio * horizon * 0.16);
418:     }
419:     g.lineTo(W + 20, horizon + 20);
420:     g.closePath();
421:     g.fill();
422:     g.restore();
423:   }
424: 
425:   function drawScenery(scroll, dt) {
426:     const themeIndex = run ? run.level.themeIndex : Math.floor(((meta.sector || 1) - 1) / 2) % THEMES.length;
427:     const theme = THEMES[themeIndex];
428:     const W = view.W;
429:     const H = view.H;
430:     const ground = view.groundY;
431:     const horizon = view.horizonY;
432: 
433:     // Low ruins and dead trees, scrolling slower than the ground.
434:     const ruinGap = W < 620 ? 160 : 230;
435:     const ruinOffset = scroll * 0.1 % ruinGap;
436:     ctx.save();
437:     for (let i = -1; i < W / ruinGap + 2; i++) {
438:       const x = i * ruinGap - ruinOffset;
439:       const r = hash(i * 7.7 + 3);
440:       const h = 35 + r * 85;
441:       const w = 18 + hash(i * 3.2) * 30;
442:       ctx.fillStyle = "rgba(13, 7, 24, 0.32)";
443:       ctx.fillRect(x, horizon + 12 - h, w, h);
444:       if (r > 0.5) {
445:         ctx.fillRect(x + w * 0.25, horizon + 12 - h - 15, 4, 15);
446:         ctx.fillRect(x + w * 0.25 - 3, horizon + 12 - h - 16, 10, 3);
447:       }
448:       // A few window lights.
449:       ctx.fillStyle = `rgba(255, 214, 122, ${0.08 + r * 0.09})`;
450:       ctx.fillRect(x + 5, horizon + 12 - h + 10, 3, 5);
451:       if (r > 0.4) ctx.fillRect(x + w - 8, horizon + 12 - h + 25, 3, 5);
452:     }
453:     ctx.restore();
454: 
455:     // Utility poles in the middle distance.
456:     const poleGap = W < 620 ? 155 : 210;
457:     const poleOffset = scroll * 0.34 % poleGap;
458:     ctx.save();
459:     for (let i = -1; i < W / poleGap + 2; i++) {
460:       const x = i * poleGap - poleOffset;
461:       const h = 55 + hash(i * 4.2) * 35;
462:       ctx.strokeStyle = "rgba(12, 8, 22, 0.46)";
463:       ctx.lineWidth = 3;
464:       ctx.beginPath();
465:       ctx.moveTo(x, horizon + 18);
466:       ctx.lineTo(x, horizon + 18 - h);
467:       ctx.moveTo(x - 11, horizon + 10 - h);
468:       ctx.lineTo(x + 11, horizon + 10 - h);
469:       ctx.stroke();
470:       ctx.strokeStyle = "rgba(12, 8, 22, 0.18)";
471:       ctx.lineWidth = 1;
472:       ctx.beginPath();
473:       ctx.moveTo(x + 11, horizon + 10 - h);
474:       ctx.quadraticCurveTo(x + poleGap * 0.5, horizon - h * 0.15, x + poleGap, horizon + 10 - h);
475:       ctx.stroke();
476:     }
477:     ctx.restore();
478: 
479:     // Ground slab.
480:     const groundGrad = ctx.createLinearGradient(0, horizon, 0, H);
481:     groundGrad.addColorStop(0, theme.groundTop);
482:     groundGrad.addColorStop(0.36, theme.ground);
483:     groundGrad.addColorStop(1, theme.groundDeep);
484:     ctx.fillStyle = groundGrad;
485:     ctx.fillRect(0, horizon + 5, W, H - horizon);
486: 
487:     // Horizon rim light.
488:     const rim = ctx.createLinearGradient(0, horizon - 3, 0, horizon + 22);
489:     rim.addColorStop(0, "rgba(255,255,255,0)");
490:     rim.addColorStop(0.45, theme.haze);
491:     rim.addColorStop(1, "rgba(255,255,255,0)");
492:     ctx.fillStyle = rim;
493:     ctx.fillRect(0, horizon - 3, W, 26);
494: 
495:     // The running lane. Its motion is the strongest cue that the hero is moving.
496:     const laneY = ground + 6;
497:     ctx.fillStyle = "rgba(8, 5, 15, 0.24)";
498:     ctx.fillRect(0, laneY, W, H - laneY);
499:     const scrollFast = scroll * 1.18;
500:     const dashGap = W < 620 ? 88 : 128;
501:     const dashOff = scrollFast % dashGap;
502:     for (let i = -1; i < W / dashGap + 2; i++) {
503:       const x = i * dashGap - dashOff;
504:       const y = laneY + 18 + (i % 2) * 19;
505:       ctx.fillStyle = "rgba(255, 245, 214, 0.085)";
506:       ctx.beginPath();
507:       ctx.moveTo(x + 11, y);
508:       ctx.lineTo(x + 57, y);
509:       ctx.lineTo(x + 52, y + 4);
510:       ctx.lineTo(x + 7, y + 4);
511:       ctx.closePath();
512:       ctx.fill();
513:     }
514: 
515:     // Scrolling stones and grass tufts.
516:     const pebbleGap = 58;
517:     const pebbleOff = scrollFast * 1.6 % pebbleGap;
518:     for (let i = -1; i < W / pebbleGap + 2; i++) {
519:       const x = i * pebbleGap - pebbleOff;
520:       const r = hash(i * 5.4 + 9);
521:       const y = ground + 24 + r * (H - ground - 33);
522:       ctx.fillStyle = r > 0.5 ? "rgba(255, 221, 174, 0.09)" : "rgba(0,0,0,0.2)";
523:       ctx.beginPath();
524:       ctx.ellipse(x, y, 3 + r * 8, 1.5 + r * 3.5, 0, 0, TAU);
525:       ctx.fill();
526:     }
527: 
528:     const tuftGap = 43;
529:     const tuftOff = scroll * 1.4 % tuftGap;
530:     for (let i = -1; i < W / tuftGap + 2; i++) {
531:       const x = i * tuftGap - tuftOff;
532:       const r = hash(i * 8.3 + 1);
533:       if (r < 0.25) continue;
534:       const h = 5 + r * 11;
535:       ctx.strokeStyle = theme.grass;
536:       ctx.globalAlpha = 0.22 + r * 0.3;
537:       ctx.lineWidth = 1.6;
538:       ctx.beginPath();
539:       ctx.moveTo(x, ground + 8);
540:       ctx.quadraticCurveTo(x - 3, ground + 8 - h * 0.6, x - 5 - r * 4, ground + 8 - h);
541:       ctx.moveTo(x + 2, ground + 8);
542:       ctx.quadraticCurveTo(x + 4, ground + 8 - h * 0.5, x + 3 + r * 3, ground + 8 - h * 0.8);
543:       ctx.stroke();
544:     }
545:     ctx.globalAlpha = 1;
546: 
547:     // Tiny drifting spores / fireflies.
548:     for (let i = 0; i < 14; i++) {
549:       const x = (hash(i * 2.2) * W + worldTime * (8 + hash(i) * 8)) % W;
550:       const y = horizon + 20 + hash(i * 7.1) * (H - horizon - 50);
551:       const a = 0.12 + Math.sin(worldTime * 1.4 + i) * 0.08;
552:       ctx.fillStyle = `rgba(255, 233, 168, ${Math.max(0, a)})`;
553:       ctx.beginPath();
554:       ctx.arc(x, y, 1 + hash(i * 9) * 1.5, 0, TAU);
555:       ctx.fill();
556:     }
557: 
558:     drawForegroundGrass(scroll, theme);
559:   }
560: 
561:   function drawForegroundGrass(scroll, theme) {
562:     const W = view.W;
563:     const H = view.H;
564:     const gap = 175;
565:     const off = (scroll * 1.9) % gap;
566:     ctx.save();
567:     for (let i = -1; i < W / gap + 2; i++) {
568:       const x = i * gap - off;
569:       const r = hash(i * 6.6 + 2);
570:       const h = 24 + r * 42;
571:       ctx.globalAlpha = 0.32;
572:       ctx.strokeStyle = theme.grass;
573:       ctx.lineWidth = 2.2;
574:       ctx.beginPath();
575:       ctx.moveTo(x, H + 4);
576:       ctx.quadraticCurveTo(x - 8, H - h * 0.65, x - 22 - r * 14, H - h);
577:       ctx.moveTo(x + 4, H + 4);
578:       ctx.quadraticCurveTo(x + 14, H - h * 0.7, x + 26 + r * 12, H - h * 0.74);
579:       ctx.stroke();
580:     }
581:     ctx.restore();
582:   }
