710:   function dropCoins(x, y, amount) {
711:     const count = amount >= 20 ? 5 : amount >= 5 ? 2 : 1;
712:     const each = Math.floor(amount / count);
713:     let left = amount;
714:     for (let i = 0; i < count; i++) {
715:       const value = i === count - 1 ? left : each;
716:       left -= value;
717:       pickups.push({ x: x + rand(-10, 10), y: y + rand(-10, 8), vx: rand(-60, 25), vy: rand(-170, -70), value, life: 9, r: 7, phase: rand(0, TAU) });
718:     }
719:   }
