739:       ui.clearBossLine.textContent = `${run.level.boss} has been erased. The next road is calling.`;
740:       ui.clearKills.textContent = run.kills;
741:       ui.clearCoins.textContent = run.coins;
742:       ui.clearCombo.textContent = run.bestCombo;
743:       setScene("clear");
744:       sound("clear");
745:     } else {
746:       meta.coins += run.coins;
747:       saveMeta(); updateMetaUI();
748:       ui.deadSector.textContent = pad2(run.level.sector);
749:       ui.deadKills.textContent = run.kills;
750:       ui.deadCoins.textContent = run.coins;
751:       setScene("dead");
