896:   function drawPlayer(actor, now) {
897:     const s = playerScale();
898:     const moving = scene === "playing" || actor.menu;
899:     const stride = moving ? Math.sin(now * 10) : 0;
900:     const x = actor.x; const y = actor.y;
901:     ctx.save();
902:     ctx.translate(x, y);
903:     ctx.scale(s, s);
904:     if (actor.invuln > 0 && Math.floor(now * 18) % 2) ctx.globalAlpha = 0.55;
905:     // Ground shadow
906:     ctx.fillStyle = "rgba(8,4,16,0.42)";
907:     ctx.beginPath(); ctx.ellipse(-4, 3, 35, 8, 0, 0, TAU); ctx.fill();
908:     // Back leg and boot
909:     ctx.strokeStyle = "#26304a"; ctx.lineWidth = 10; ctx.lineCap = "round";
910:     ctx.beginPath(); ctx.moveTo(-8, -28); ctx.lineTo(-16 + stride * 7, -10); ctx.lineTo(-19 + stride * 10, -2); ctx.stroke();
911:     ctx.fillStyle = "#22283d"; ctx.beginPath(); ctx.roundRect(-26 + stride * 10, -7, 17, 7, 3); ctx.fill();
912:     // Front leg
913:     ctx.strokeStyle = "#38435c"; ctx.lineWidth = 11;
914:     ctx.beginPath(); ctx.moveTo(6, -29); ctx.lineTo(13 - stride * 7, -12); ctx.lineTo(20 - stride * 10, -2); ctx.stroke();
915:     ctx.fillStyle = "#303449"; ctx.beginPath(); ctx.roundRect(11 - stride * 10, -7, 19, 7, 3); ctx.fill();
916:     // Jacket torso
