949:   function drawEnemy(enemy) {
950:     const perspective = clamp(0.7 + (enemy.y - view.horizonY) / (view.groundY - view.horizonY) * 0.36, 0.65, 1.12);
951:     const s = actorScale() * perspective;
952:     const bob = Math.sin(enemy.bob) * 2.4;
953:     ctx.save(); ctx.translate(enemy.x, enemy.y + bob); ctx.scale(s, s);
954:     const r = enemy.radius / Math.max(0.7, s);
955:     ctx.fillStyle = "rgba(8,4,16,0.35)"; ctx.beginPath(); ctx.ellipse(0, 0, r * 1.12, 6, 0, 0, TAU); ctx.fill();
956:     const body = enemy.hit > 0 ? "#fff4d8" : enemy.color;
957:     // lurching legs and claws
958:     ctx.strokeStyle = body; ctx.lineWidth = enemy.type === "brute" ? 9 : 6; ctx.lineCap = "round";
959:     ctx.beginPath(); ctx.moveTo(-7, -20); ctx.lineTo(-12 + Math.sin(enemy.bob) * 5, -4); ctx.moveTo(7, -20); ctx.lineTo(13 - Math.sin(enemy.bob) * 5, -4); ctx.stroke();
960:     ctx.fillStyle = body;
961:     if (enemy.type === "brute") {
962:       ctx.beginPath(); ctx.ellipse(0, -34, 24, 27, -0.12, 0, TAU); ctx.fill();
963:       ctx.beginPath(); ctx.ellipse(2, -61, 19, 18, 0, 0, TAU); ctx.fill();
964:       ctx.fillStyle = "#462e43"; ctx.fillRect(4, -64, 17, 6);
965:       ctx.fillStyle = "#ffed91"; ctx.fillRect(8, -63, 5, 3); ctx.fillRect(17, -63, 5, 3);
966:       ctx.fillStyle = "#f5d894"; ctx.fillRect(-16, -23, 8, 4);
967:     } else {
968:       ctx.beginPath(); ctx.ellipse(0, -31, 16, 23, 0.1, 0, TAU); ctx.fill();
969:       ctx.beginPath(); ctx.ellipse(2, -56, 14, 14, 0, 0, TAU); ctx.fill();
970:       ctx.fillStyle = "#35283f"; ctx.beginPath(); ctx.ellipse(5, -58, 12, 5, 0, 0, TAU); ctx.fill();
971:       ctx.fillStyle = enemy.type === "spitter" ? "#bbf773" : "#ffdd72";
972:       ctx.fillRect(3, -59, 4, 3); ctx.fillRect(12, -59, 4, 3);
973:       ctx.fillStyle = "#eee0bd"; ctx.fillRect(6, -48, 8, 3);
974:       ctx.strokeStyle = body; ctx.lineWidth = 5; ctx.beginPath(); ctx.moveTo(-11, -39); ctx.lineTo(-21, -26); ctx.moveTo(11, -38); ctx.lineTo(19, -28); ctx.stroke();
975:       ctx.fillStyle = "#f5e4bd"; ctx.fillRect(-24, -27, 8, 3); ctx.fillRect(16, -29, 8, 3);
