425:   function drawScenery(scroll, dt) {
426:     const themeIndex = run ? run.level.themeIndex : Math.floor(((meta.sector || 1) - 1) / 2) % THEMES.length;
427:     const theme = THEMES[themeIndex];
428:     const W = view.W;
429:     const H = view.H;
430:     const ground = view.groundY;
431:     const horizon = view.horizonY;
432: 
433:     // Low ruins and dead trees, scrolling slower than the ground.
434:     const ruinGap = W < 620 ? 160 : 230;
435:     const ruinOffset = scroll * 0.1 % ruinGap;
436:     ctx.save();
437:     for (let i = -1; i < W / ruinGap + 2; i++) {
438:       const x = i * ruinGap - ruinOffset;
439:       const r = hash(i * 7.7 + 3);
440:       const h = 35 + r * 85;
441:       const w = 18 + hash(i * 3.2) * 30;
442:       ctx.fillStyle = "rgba(13, 7, 24, 0.32)";
443:       ctx.fillRect(x, horizon + 12 - h, w, h);
444:       if (r > 0.5) {
445:         ctx.fillRect(x + w * 0.25, horizon + 12 - h - 15, 4, 15);
446:         ctx.fillRect(x + w * 0.25 - 3, horizon + 12 - h - 16, 10, 3);
447:       }
448:       // A few window lights.
449:       ctx.fillStyle = `rgba(255, 214, 122, ${0.08 + r * 0.09})`;
450:       ctx.fillRect(x + 5, horizon + 12 - h + 10, 3, 5);
451:       if (r > 0.4) ctx.fillRect(x + w - 8, horizon + 12 - h + 25, 3, 5);
452:     }
453:     ctx.restore();
454: 
455:     // Utility poles in the middle distance.
456:     const poleGap = W < 620 ? 155 : 210;
457:     const poleOffset = scroll * 0.34 % poleGap;
458:     ctx.save();
459:     for (let i = -1; i < W / poleGap + 2; i++) {
460:       const x = i * poleGap - poleOffset;
461:       const h = 55 + hash(i * 4.2) * 35;
462:       ctx.strokeStyle = "rgba(12, 8, 22, 0.46)";
463:       ctx.lineWidth = 3;
464:       ctx.beginPath();
465:       ctx.moveTo(x, horizon + 18);
466:       ctx.lineTo(x, horizon + 18 - h);
467:       ctx.moveTo(x - 11, horizon + 10 - h);
468:       ctx.lineTo(x + 11, horizon + 10 - h);
469:       ctx.stroke();
470:       ctx.strokeStyle = "rgba(12, 8, 22, 0.18)";
471:       ctx.lineWidth = 1;
472:       ctx.beginPath();
473:       ctx.moveTo(x + 11, horizon + 10 - h);
474:       ctx.quadraticCurveTo(x + poleGap * 0.5, horizon - h * 0.15, x + poleGap, horizon + 10 - h);
475:       ctx.stroke();
476:     }
477:     ctx.restore();
478: 
479:     // Ground slab.
480:     const groundGrad = ctx.createLinearGradient(0, horizon, 0, H);
481:     groundGrad.addColorStop(0, theme.groundTop);
482:     groundGrad.addColorStop(0.36, theme.ground);
483:     groundGrad.addColorStop(1, theme.groundDeep);
484:     ctx.fillStyle = groundGrad;
485:     ctx.fillRect(0, horizon + 5, W, H - horizon);
486: 
487:     // Horizon rim light.
488:     const rim = ctx.createLinearGradient(0, horizon - 3, 0, horizon + 22);
489:     rim.addColorStop(0, "rgba(255,255,255,0)");
490:     rim.addColorStop(0.45, theme.haze);
491:     rim.addColorStop(1, "rgba(255,255,255,0)");
492:     ctx.fillStyle = rim;
493:     ctx.fillRect(0, horizon - 3, W, 26);
494: 
495:     // The running lane. Its motion is the strongest cue that the hero is moving.
496:     const laneY = ground + 6;
497:     ctx.fillStyle = "rgba(8, 5, 15, 0.24)";
498:     ctx.fillRect(0, laneY, W, H - laneY);
499:     const scrollFast = scroll * 1.18;
500:     const dashGap = W < 620 ? 88 : 128;
501:     const dashOff = scrollFast % dashGap;
502:     for (let i = -1; i < W / dashGap + 2; i++) {
503:       const x = i * dashGap - dashOff;
504:       const y = laneY + 18 + (i % 2) * 19;
505:       ctx.fillStyle = "rgba(255, 245, 214, 0.085)";
506:       ctx.beginPath();
507:       ctx.moveTo(x + 11, y);
508:       ctx.lineTo(x + 57, y);
509:       ctx.lineTo(x + 52, y + 4);
510:       ctx.lineTo(x + 7, y + 4);
511:       ctx.closePath();
512:       ctx.fill();
513:     }
514: 
515:     // Scrolling stones and grass tufts.
516:     const pebbleGap = 58;
517:     const pebbleOff = scrollFast * 1.6 % pebbleGap;
518:     for (let i = -1; i < W / pebbleGap + 2; i++) {
519:       const x = i * pebbleGap - pebbleOff;
520:       const r = hash(i * 5.4 + 9);
521:       const y = ground + 24 + r * (H - ground - 33);
522:       ctx.fillStyle = r > 0.5 ? "rgba(255, 221, 174, 0.09)" : "rgba(0,0,0,0.2)";
523:       ctx.beginPath();
524:       ctx.ellipse(x, y, 3 + r * 8, 1.5 + r * 3.5, 0, 0, TAU);
525:       ctx.fill();
526:     }
527: 
528:     const tuftGap = 43;
529:     const tuftOff = scroll * 1.4 % tuftGap;
530:     for (let i = -1; i < W / tuftGap + 2; i++) {
531:       const x = i * tuftGap - tuftOff;
532:       const r = hash(i * 8.3 + 1);
533:       if (r < 0.25) continue;
534:       const h = 5 + r * 11;
535:       ctx.strokeStyle = theme.grass;
536:       ctx.globalAlpha = 0.22 + r * 0.3;
537:       ctx.lineWidth = 1.6;
538:       ctx.beginPath();
539:       ctx.moveTo(x, ground + 8);
540:       ctx.quadraticCurveTo(x - 3, ground + 8 - h * 0.6, x - 5 - r * 4, ground + 8 - h);
541:       ctx.moveTo(x + 2, ground + 8);
542:       ctx.quadraticCurveTo(x + 4, ground + 8 - h * 0.5, x + 3 + r * 3, ground + 8 - h * 0.8);
543:       ctx.stroke();
544:     }
545:     ctx.globalAlpha = 1;
546: 
547:     // Tiny drifting spores / fireflies.
548:     for (let i = 0; i < 14; i++) {
549:       const x = (hash(i * 2.2) * W + worldTime * (8 + hash(i) * 8)) % W;
550:       const y = horizon + 20 + hash(i * 7.1) * (H - horizon - 50);
551:       const a = 0.12 + Math.sin(worldTime * 1.4 + i) * 0.08;
552:       ctx.fillStyle = `rgba(255, 233, 168, ${Math.max(0, a)})`;
553:       ctx.beginPath();
554:       ctx.arc(x, y, 1 + hash(i * 9) * 1.5, 0, TAU);
555:       ctx.fill();
556:     }
557: 
558:     drawForegroundGrass(scroll, theme);
559:   }
