828:     if (boss) {
829:       boss.bob += dt * 2.6; boss.hit = Math.max(0, boss.hit - dt); boss.attackCd -= dt;
830:       boss.x = Math.max(view.W * 0.7, boss.x - 24 * dt);
831:       boss.y = view.groundY - 70 * actorScale() + Math.sin(boss.bob) * 8;
832:       if (boss.attackCd <= 0) {
833:         boss.attackCd = Math.max(0.8, 1.7 - run.level.difficulty * 0.04);
834:         const a = Math.atan2(player.y - 55 * playerScale() - boss.y, player.x + 20 - boss.x);
835:         const spread = run.level.sector > 3 ? [-0.13, 0, 0.13] : [0];
836:         for (const offset of spread) hazards.push({ x: boss.x - 36, y: boss.y - 26, vx: Math.cos(a + offset) * 290, vy: Math.sin(a + offset) * 290, life: 3, r: 10, damage: 15 + run.level.difficulty * 1.5, color: "#ff597a" });
837:         burst(boss.x - 30, boss.y - 26, "#ff597a", 5, 65); sound("spit");
838:       }
839:     }
