841:     for (const bullet of bullets) {
842:       bullet.x += bullet.vx * dt; bullet.y += bullet.vy * dt; bullet.life -= dt;
843:       for (const enemy of enemies) {
844:         if (enemy.dead || bullet.hitIds.includes(enemy.id)) continue;
845:         if (Math.hypot(enemy.x - bullet.x, enemy.y - enemy.radius * 0.5 - bullet.y) < enemy.radius * 0.8 + bullet.r) {
846:           enemy.hp -= bullet.damage; enemy.hit = 0.12; bullet.life = 0;
847:           burst(bullet.x, bullet.y, bullet.color, 3, 70); sound("impact");
848:           if (bullet.splash) for (const other of enemies) if (!other.dead && other !== enemy && Math.hypot(other.x - enemy.x, other.y - enemy.y) < bullet.splash) other.hp -= bullet.damage * 0.65;
849:           if (bullet.chain) {
850:             let left = bullet.chain;
851:             for (const other of enemies) if (!other.dead && other !== enemy && Math.hypot(other.x - enemy.x, other.y - enemy.y) < 150 && left-- > 0) { other.hp -= bullet.damage * 0.65; burst(other.x, other.y - 10, "#69efff", 6, 95); }
852:           }
853:           if (enemy.hp <= 0) killEnemy(enemy);
854:           break;
855:         }
856:       }
857:       if (boss && bullet.life > 0 && Math.hypot(boss.x - bullet.x, boss.y - 28 - bullet.y) < boss.radius * 0.82 + bullet.r) { hurtBoss(bullet.damage); bullet.life = 0; burst(bullet.x, bullet.y, bullet.color, 4, 90); }
858:     }
859:     bullets = bullets.filter((bullet) => bullet.life > 0 && bullet.x < view.W + 80 && bullet.y > -30 && bullet.y < view.H + 20);
860:     enemies = enemies.filter((enemy) => !enemy.dead && enemy.x > -80);
861: 
862:     for (const hazard of hazards) {
863:       hazard.x += hazard.vx * dt; hazard.y += hazard.vy * dt; hazard.life -= dt;
864:       if (Math.hypot(hazard.x - player.x, hazard.y - (player.y - 52 * playerScale())) < hazard.r + 28 * playerScale()) { hazard.life = 0; damagePlayer(hazard.damage); burst(hazard.x, hazard.y, hazard.color, 8, 110); }
865:     }
866:     hazards = hazards.filter((hazard) => hazard.life > 0 && hazard.x > -30 && hazard.x < view.W + 30);
867: 
868:     for (const coin of pickups) {
869:       coin.phase += dt * 5; coin.vy += 360 * dt; coin.x += coin.vx * dt; coin.y += coin.vy * dt;
870:       const magnet = 100 + upgradeValue("magnet") * 45;
871:       const distance = Math.hypot(player.x - coin.x, player.y - coin.y);
872:       if (distance < magnet) { const force = (1 - distance / magnet) * 580; coin.vx += (player.x - coin.x) / Math.max(1, distance) * force * dt; coin.vy += (player.y - coin.y) / Math.max(1, distance) * force * dt; }
873:       if (distance < 45 * playerScale()) { run.coins += coin.value; coin.life = 0; burst(coin.x, coin.y, "#ffe66d", 4, 75); floatText(player.x, player.y - 110, `+${coin.value}`, "#ffe66d"); sound("coin"); }
874:       coin.life -= dt;
