879:     particles = particles.filter((part) => part.life > 0);
880:     for (const floater of floaters) { floater.life -= dt; floater.y -= 30 * dt; }
881:     floaters = floaters.filter((floater) => floater.life > 0);
882:     run.comboTimer -= dt;
883:     if (run.comboTimer <= 0) run.combo = 0;
884:     shake = Math.max(0, shake - dt * 24);
885:     flash = Math.max(0, flash - dt * 1.8);
