960:     ctx.fillStyle = body;
961:     if (enemy.type === "brute") {
962:       ctx.beginPath(); ctx.ellipse(0, -34, 24, 27, -0.12, 0, TAU); ctx.fill();
963:       ctx.beginPath(); ctx.ellipse(2, -61, 19, 18, 0, 0, TAU); ctx.fill();
964:       ctx.fillStyle = "#462e43"; ctx.fillRect(4, -64, 17, 6);
965:       ctx.fillStyle = "#ffed91"; ctx.fillRect(8, -63, 5, 3); ctx.fillRect(17, -63, 5, 3);
