969:       ctx.beginPath(); ctx.ellipse(2, -56, 14, 14, 0, 0, TAU); ctx.fill();
970:       ctx.fillStyle = "#35283f"; ctx.beginPath(); ctx.ellipse(5, -58, 12, 5, 0, 0, TAU); ctx.fill();
971:       ctx.fillStyle = enemy.type === "spitter" ? "#bbf773" : "#ffdd72";
972:       ctx.fillRect(3, -59, 4, 3); ctx.fillRect(12, -59, 4, 3);
