1003:   function drawWorld(now) {
1004:     if (!backdrop) buildBackdrop();
1005:     ctx.setTransform(view.DPR, 0, 0, view.DPR, 0, 0);
1006:     ctx.fillStyle = "#100b21"; ctx.fillRect(0, 0, view.W, view.H);
1007:     const shakeX = shake ? rand(-shake, shake) : 0; const shakeY = shake ? rand(-shake * 0.5, shake * 0.5) : 0;
1008:     ctx.save(); ctx.translate(shakeX, shakeY);
1009:     ctx.drawImage(backdrop, 0, 0, view.W, view.H);
1010:     drawScenery(run ? run.scroll : menu.scroll, 0);
1011:     if (scene === "playing" || ["paused", "clear", "dead"].includes(scene)) {
1012:       const sorted = enemies.slice().sort((a, b) => a.y - b.y);
1013:       for (const enemy of sorted) drawEnemy(enemy);
1014:       drawBoss();
1015:       for (const hazard of hazards) {
1016:         ctx.fillStyle = hazard.color; ctx.shadowColor = hazard.color; ctx.shadowBlur = 12;
1017:         ctx.beginPath(); ctx.arc(hazard.x, hazard.y, hazard.r, 0, TAU); ctx.fill(); ctx.shadowBlur = 0;
1018:         ctx.fillStyle = "rgba(255,255,255,0.7)"; ctx.beginPath(); ctx.arc(hazard.x - 2, hazard.y - 2, hazard.r * 0.35, 0, TAU); ctx.fill();
1019:       }
1020:       for (const bullet of bullets) {
1021:         ctx.strokeStyle = bullet.color; ctx.lineWidth = bullet.r * 1.4; ctx.lineCap = "round"; ctx.globalAlpha = 0.45;
1022:         ctx.beginPath(); ctx.moveTo(bullet.x - bullet.vx * 0.018, bullet.y - bullet.vy * 0.018); ctx.lineTo(bullet.x, bullet.y); ctx.stroke(); ctx.globalAlpha = 1;
1023:         ctx.fillStyle = "#fff8d5"; ctx.beginPath(); ctx.arc(bullet.x, bullet.y, bullet.r, 0, TAU); ctx.fill();
1024:       }
1025:       for (const coin of pickups) {
1026:         const bob = Math.sin(coin.phase) * 3;
1027:         ctx.fillStyle = "#c87811"; ctx.beginPath(); ctx.arc(coin.x, coin.y + bob, coin.r, 0, TAU); ctx.fill();
1028:         ctx.fillStyle = "#ffe362"; ctx.beginPath(); ctx.arc(coin.x, coin.y + bob - 1, coin.r - 2, 0, TAU); ctx.fill();
1029:         ctx.fillStyle = "#fff4b1"; ctx.fillRect(coin.x - 1, coin.y + bob - 4, 2, 7);
1030:       }
1031:       if (player) drawPlayer(player, now);
1032:       for (const part of particles) {
1033:         const alpha = clamp(part.life / part.maxLife, 0, 1);
1034:         ctx.globalAlpha = alpha; ctx.strokeStyle = part.color; ctx.fillStyle = part.color;
1035:         if (part.ring) { ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(part.x, part.y, part.size * (1.4 - alpha), 0, TAU); ctx.stroke(); }
1036:         else { ctx.beginPath(); ctx.arc(part.x, part.y, Math.max(0.7, part.size * alpha), 0, TAU); ctx.fill(); }
1037:       }
1038:       ctx.globalAlpha = 1;
1039:       for (const text of floaters) { ctx.globalAlpha = clamp(text.life / text.maxLife, 0, 1); ctx.font = "900 15px Outfit, sans-serif"; ctx.textAlign = "center"; ctx.lineWidth = 3; ctx.strokeStyle = "rgba(20,12,32,.8)"; ctx.strokeText(text.text, text.x, text.y); ctx.fillStyle = text.color; ctx.fillText(text.text, text.x, text.y); }
1040:       ctx.globalAlpha = 1;
1041:     } else {
1042:       // A tiny animated title-scene vignette; the actual game remains in the same canvas.
1043:       if (!player) player = makePlayer();
1044:       player.menu = true; player.aimAngle = -0.48;
1045:       drawPlayer(player, now);
1046:       for (let i = 0; i < 3; i++) drawEnemy({ x: view.W * (0.73 + i * 0.13), y: view.groundY - 18 - i * 12, radius: 20, bob: now * 4 + i * 1.8, type: i === 1 ? "brute" : "runner", color: ["#91d95e", "#d88752", "#c675b6"][i], hp: 20, maxHp: 20, hit: 0 });
1047:     }
1048:     ctx.restore();
1049:     if (flash > 0) { ctx.fillStyle = `rgba(${flashColor},${flash})`; ctx.fillRect(0, 0, view.W, view.H); }
1050:     if (scene === "playing" && input.aiming && player) {
1051:       const mx = player.x + 38 * playerScale(); const my = player.y - 57 * playerScale();
1052:       ctx.strokeStyle = "rgba(217,255,69,.15)"; ctx.setLineDash([5, 8]); ctx.beginPath(); ctx.moveTo(mx, my); ctx.lineTo(mx + Math.cos(player.aimAngle) * 100, my + Math.sin(player.aimAngle) * 100); ctx.stroke(); ctx.setLineDash([]);
1053:     }
1054:   }
