1056:   function nearestTarget(x, y, maxDistance = Infinity) {
1057:     let best = null; let bestDist = maxDistance * maxDistance;
1058:     for (const enemy of enemies) {
1059:       if (enemy.dead) continue;
1060:       const d = (enemy.x - x) ** 2 + (enemy.y - enemy.radius * 0.6 - y) ** 2;
1061:       if (d < bestDist) { bestDist = d; best = { x: enemy.x, y: enemy.y - enemy.radius * 0.6 }; }
1062:     }
1063:     if (boss) { const d = (boss.x - x) ** 2 + (boss.y - 28 - y) ** 2; if (d < bestDist) best = { x: boss.x, y: boss.y - 28 }; }
1064:     return best;
1065:   }
